import urllib.request,urllib.error,sys
u='https://api.telegram.org/botNOT_A_REAL_TOKEN/getMe'
def probe(opener):
 try:
  opener.open(u,timeout=8).close()
  return True
 except urllib.error.HTTPError:
  return True
 except Exception:
  return False
direct=probe(urllib.request.build_opener(urllib.request.ProxyHandler({})))
default=probe(urllib.request.build_opener())
if default and direct:sys.exit(0)
if default and not direct:sys.exit(80)
if direct and not default:sys.exit(81)
sys.exit(82)
